locals {
  broker_image  = "1.28@sha256:146adea4768b83c607d0bdfa4188464e3da6e0a3ad4475db1d1d8f64f27c29cc"
  gateway_image = "1.28@sha256:146adea4768b83c607d0bdfa4188464e3da6e0a3ad4475db1d1d8f64f27c29cc"
}

# … the broker release stays as it is …

resource "helm_release" "gateway" {
  name      = "gateway"
  namespace = "ai-agents"
  chart     = "./ai-agents-service"

  values = [yamlencode({
    fullnameOverride = "gateway"
    replicaCount     = 2
    image            = { tag = local.gateway_image }
  })]

  depends_on = [helm_release.broker]
}

resource "helm_release" "slack_app" {
  name      = "slack-app"
  namespace = "ai-agents"
  chart     = "./ai-agents-service"

  values = [yamlencode({
    fullnameOverride = "slack-app"
    replicaCount     = 1
    image            = { tag = local.gateway_image }
  })]

  depends_on = [helm_release.broker]
}
